// @ts-ignore Generated by the Cloudflare build.
import handler from "./.open-next/worker.js";
import type { D1Database, ExportedHandler, MessageBatch, ScheduledController } from "@cloudflare/workers-types";

import { d1CostMetrics, isHubQueueJob, jobsForCron, processHubQueueJob } from "./lib/server/hub-maintenance-jobs";
import { isPublicApiCacheableResponse, isPublicApiCacheCandidate, publicApiCacheKey } from "./lib/server/public-api-cache";
import {
  FEED_REALTIME_SHARDS,
  normalizeFeedRealtimeShard,
  validateFeedRealtimeUpgrade,
  type FeedRealtimeEvent,
} from "./lib/feed-realtime";
import { enforceHubApiRateLimit } from "./lib/edge-api-rate-limit";
import { refuseRevokedModerationSession } from "./lib/server/moderation-admin-revocation-gate";
import { decideHubRequest, type HubRequestPolicyEnv } from "./lib/hub-request-policy";
import { HUB_LOCALE_COOKIE } from "./lib/i18n";
import { WORKER_DATA_PREFIX } from "./lib/server/worker-data";
export { FeedRealtimeShard } from "./lib/server/feed-realtime-object";
import { serveBoughtModel } from "./lib/server/world-bought";
export { WorldZone } from "./lib/server/world-zone-object";

function feedShard(env: CloudflareEnv, index: number) {
  return env.FEED_REALTIME.getByName(`public-feed-${normalizeFeedRealtimeShard(index)}`);
}

function hasLocaleCookie(request: Request): boolean {
  const cookie = request.headers.get("cookie");
  return Boolean(cookie) && new RegExp(`(?:^|;\\s*)${HUB_LOCALE_COOKIE}=`).test(cookie!);
}

function serializeLocaleCookie(cookie: NonNullable<Extract<ReturnType<typeof decideHubRequest>, { type: "continue" }>["localeCookie"]>) {
  const parts = [
    `${cookie.name}=${cookie.value}`,
    `Path=${cookie.path}`,
    `Max-Age=${cookie.maxAge}`,
    "SameSite=Lax",
  ];
  if (cookie.secure) parts.push("Secure");
  return parts.join("; ");
}

export default {
  async fetch(request, env, context) {
    const url = new URL(request.url);
    /*
     * Read-only data files live in the static assets (lib/server/worker-data.ts)
     * and are listed in `assets.run_worker_first`, so this is the only way a
     * browser can reach them: refuse. The code reads them through the ASSETS
     * binding, which does not pass through here.
     */
    if (url.pathname.startsWith(WORKER_DATA_PREFIX)) {
      return new Response("Not found", { status: 404, headers: { "Cache-Control": "no-store" } });
    }
    /*
     * proxy.ts cannot run here: Next 16 pins it to the Node.js runtime and the
     * Cloudflare adapter refuses to bundle that, so the build parks it. This
     * entry point is the equivalent unmissable position, and both surfaces
     * share lib/hub-request-policy.ts so the rules cannot drift apart.
     */
    const policy = decideHubRequest(
      {
        pathname: url.pathname,
        search: url.search,
        requestedLocale: url.searchParams.get("lang"),
        acceptLanguage: request.headers.get("accept-language"),
        hasLocaleCookie: hasLocaleCookie(request as unknown as Request),
        secure: url.protocol === "https:",
        requestId: request.headers.get("cf-ray") ?? crypto.randomUUID(),
      },
      env as unknown as HubRequestPolicyEnv,
    );
    if (policy.type === "block") {
      return new Response(JSON.stringify(policy.body), {
        status: policy.status,
        headers: { ...policy.headers, "Content-Type": "application/json" },
      });
    }
    if (policy.type === "redirect") {
      const destination = new URL(url);
      destination.pathname = policy.pathname;
      destination.search = policy.search;
      return Response.redirect(destination.toString(), policy.status);
    }
    const rateLimited = await enforceHubApiRateLimit(request, env);
    if (rateLimited) return rateLimited;
    // Admin logout deny list (sync route checks cannot read D1).
    const revoked = await refuseRevokedModerationSession(
      url.pathname, request.headers.get("cookie"), (env as unknown as { HUB_DATABASE?: D1Database }).HUB_DATABASE,
    );
    if (revoked) return revoked;
    /**
     * 3Dワールドの区画へ繋ぐ。**区画ごとに1つのオブジェクト。**
     *
     * 名前で引くので、同じ区画に居る人は必ず同じ所へ繋がる。知らない区画名で
     * 部屋を無限に作らせないよう、実在するかどうかはオブジェクトの側で見る。
     */
    /**
     * 買った物の絵。**Vault と世界の間に立つ。**
     *
     * Vault の口は世界にだけ開いているので、見る人へ直に渡せない。ここで
     * 受けて、検めた版だけを配る。
     */
    const boughtMatch = url.pathname.match(/^\/bought\/([A-Za-z0-9][A-Za-z0-9_-]{0,62})\.glb$/);
    if (request.method === "GET" && boughtMatch) {
      return serveBoughtModel(request, env, boughtMatch[1]!);
    }
    if (url.pathname === "/world/live") {
      if (request.headers.get("upgrade")?.toLowerCase() !== "websocket") {
        return new Response("websocket が要ります", { status: 426 });
      }
      const zone = url.searchParams.get("zone") ?? "city";
      // **名前を検めてから引く。** そのまま渡すと、名前1つにつき1部屋できる。
      const named = /^[a-z][a-z0-9-]{0,30}$/.test(zone) ? zone : "city";
      return env.WORLD_ZONE.getByName(`zone-${named}`).fetch(request);
    }
    if (url.pathname === "/api/feed/live") {
      const upgradeError = validateFeedRealtimeUpgrade(request);
      if (upgradeError) return new Response(upgradeError.message, { status: upgradeError.status });
      return feedShard(env, normalizeFeedRealtimeShard(url.searchParams.get("shard"))).fetch(request);
    }
    /*
     * Mirrors proxy.ts's matcher: the shared policy decorates documents and API
     * responses, never the immutable static asset responses.
     */
    const decorated = <T extends { headers: Headers }>(candidate: T): T | Response => {
      if (
        url.pathname.startsWith("/_next/static")
        || url.pathname.startsWith("/_next/image")
        || url.pathname === "/favicon.ico"
      ) {
        return candidate;
      }
      // A response served from cache or the origin may carry immutable
      // headers, so decorate a copy rather than the original.
      const source = candidate as unknown as Response;
      const copy = new Response(source.body, source);
      for (const [header, value] of Object.entries(policy.headers)) {
        copy.headers.set(header, value);
      }
      if (policy.localeCookie) {
        copy.headers.append("Set-Cookie", serializeLocaleCookie(policy.localeCookie));
      }
      return copy;
    };
    const cache = isPublicApiCacheCandidate(request)
      ? (caches as CacheStorage & { default: Cache }).default
      : null;
    const cacheKey = cache ? publicApiCacheKey(request) : null;
    if (cache && cacheKey) {
      const cached = await cache.match(cacheKey);
      if (cached) return decorated(cached);
    }
    const response = await handler.fetch(request, env, context);
    if (cache && cacheKey && isPublicApiCacheableResponse(response)) {
      context.waitUntil(
        cache.put(cacheKey, response.clone()).catch(() => {
          console.warn(JSON.stringify({ event: "public_api_cache_write_failed", path: url.pathname }));
        }),
      );
    }
    if (url.pathname === "/api/social/posts" && request.method === "POST" && response.status === 201) {
      const event: FeedRealtimeEvent = {
        type: "new-post",
        eventId: crypto.randomUUID(),
        at: new Date().toISOString(),
      };
      context.waitUntil(Promise.allSettled(
        Array.from({ length: FEED_REALTIME_SHARDS }, (_, index) => feedShard(env, index).broadcastNewPost(event)),
      ).then((results) => {
        const failedShards = results.filter((result) => result.status === "rejected").length;
        if (failedShards) {
          console.warn(JSON.stringify({ event: "feed_realtime_broadcast_partial_failure", failedShards }));
        }
      }));
    }
    return decorated(response);
  },

  async scheduled(event: ScheduledController, env: CloudflareEnv) {
    const jobs = jobsForCron(event.cron);
    if (jobs.length) await env.HUB_JOBS.sendBatch(jobs.map((body) => ({ body })));
  },

  async queue(batch: MessageBatch<unknown>, env: CloudflareEnv) {
    await Promise.all(batch.messages.map(async (message) => {
      if (!isHubQueueJob(message.body)) {
        console.error(JSON.stringify({ event: "hub_job_rejected", reason: "invalid_message" }));
        message.ack();
        return;
      }
      const startedAt = Date.now();
      try {
        const result = await processHubQueueJob(message.body, env);
        message.ack();
        console.log(JSON.stringify({ event: "hub_job_completed", jobType: message.body.type, durationMs: Date.now() - startedAt, ...d1CostMetrics(result) }));
      } catch {
        console.error(JSON.stringify({ event: "hub_job_failed", jobType: message.body.type, durationMs: Date.now() - startedAt }));
        message.retry({ delaySeconds: 60 });
      }
    }));
  }
} satisfies ExportedHandler<CloudflareEnv>;

// @ts-ignore Generated by the Cloudflare build.
export { DOQueueHandler, DOShardedTagCache } from "./.open-next/worker.js";
